Q: How to download the iframe as pdf document in react?I have tried using jspdf and kendo-react-pdf but getting blank document A: <pre><code>import { useRef } from &quot;react&quot;;
import EbookLayout from &quot;@/components/ebook/EbookLayout&quot;;
import DownloadPdfButton from &quot;@/components/ebook/DownloadPdfButton&quot;;
import TableOfContents from &quot;@/components/ebook/TableOfContents&quot;;
import ChapterHeader from &quot;@/components/ebook/ChapterHeader&quot;;
import InfoCard from &quot;@/components/ebook/InfoCard&quot;;

const Index = () =&gt; {
  const contentRef = useRef&lt;HTMLDivElement&gt;(null);
  return (
    &lt;EbookLayout&gt;
      &lt;div ref={contentRef}&gt;
        &lt;DownloadPdfButton contentRef={contentRef} /&gt;

        {/* ===== CAPA ===== */}
        &lt;header className=&quot;relative overflow-hidden rounded-2xl ebook-gradient-hero mb-12&quot;&gt;
          &lt;div className=&quot;absolute inset-0 opacity-10&quot; style={{
            backgroundImage: 'radial-gradient(circle at 30% 50%, hsl(43, 90%, 50%) 0%, transparent 50%), radial-gradient(circle at 80% 20%, hsl(43, 80%, 55%) 0%, transparent 40%)'
          }} /&gt;
          &lt;div className=&quot;relative flex flex-col items-center text-center px-8 py-16 sm:py-24&quot;&gt;
            &lt;div className=&quot;w-20 h-px bg-gradient-to-r from-transparent via-primary to-transparent mb-8&quot; /&gt;
            &lt;p className=&quot;text-primary font-semibold uppercase tracking-[0.3em] text-xs mb-6&quot;&gt;
              Educação Financeira
            &lt;/p&gt;
            &lt;h1 className=&quot;text-5xl sm:text-7xl font-extrabold text-white leading-[1.1] mb-4 tracking-tight&quot;&gt;
              MENTE &lt;span className=&quot;gold-text&quot;&gt;RICA&lt;/span&gt;
            &lt;/h1&gt;
            &lt;p className=&quot;text-lg sm:text-xl text-white/70 max-w-lg font-light&quot;&gt;
              Como Usar, Multiplicar e Controlar o Dinheiro
            &lt;/p&gt;
            &lt;div className=&quot;w-20 h-px bg-gradient-to-r from-transparent via-primary to-transparent mt-8&quot; /&gt;

            {/* Ícones decorativos */}
            &lt;div className=&quot;flex gap-8 mt-10 text-primary/60 text-2xl&quot;&gt;
              &lt;span&gt;💰&lt;/span&gt;
              &lt;span&gt;📈&lt;/span&gt;
              &lt;span&gt;🧠&lt;/span&gt;
              &lt;span&gt;🔑&lt;/span&gt;
            &lt;/div&gt;
          &lt;/div&gt;
        &lt;/header&gt;

        &lt;TableOfContents /&gt;

        {/* ===== INTRODUÇÃO ===== */}
        &lt;section id=&quot;chapter-0&quot; className=&quot;mb-16&quot;&gt;
          &lt;ChapterHeader number={0} title=&quot;Introdução&quot; /&gt;
          &lt;p className=&quot;text-lg leading-relaxed text-foreground mb-4&quot;&gt;
            Hoje em dia quase todo mundo deseja ter mais dinheiro.
            Mas poucas pessoas realmente sabem como usar o dinheiro de forma inteligente.
          &lt;/p&gt;
          &lt;p className=&quot;text-lg leading-relaxed text-foreground mb-4&quot;&gt;
            Muitas pessoas ganham bem, mas continuam sempre com dificuldades financeiras.
            Outras ganham pouco, mas conseguem construir riqueza ao longo do tempo.
          &lt;/p&gt;
          &lt;p className=&quot;text-lg leading-relaxed text-foreground mb-4&quot;&gt;
            Isso acontece porque o problema não é apenas ganhar dinheiro.
          &lt;/p&gt;

          &lt;InfoCard variant=&quot;dark&quot;&gt;
            &lt;p className=&quot;text-xl font-semibold text-center italic&quot;&gt;
              &quot;O verdadeiro desafio é saber administrar o dinheiro que se ganha.&quot;
            &lt;/p&gt;
          &lt;/InfoCard&gt;

          &lt;p className=&quot;text-lg leading-relaxed text-foreground mb-4&quot;&gt;
            A riqueza não começa na conta bancária. Ela começa na &lt;strong&gt;mentalidade&lt;/strong&gt;.
          &lt;/p&gt;

          &lt;InfoCard variant=&quot;highlight&quot; title=&quot;📖 Neste ebook você vai aprender:&quot;&gt;
            &lt;ul className=&quot;list-disc list-inside space-y-2&quot;&gt;
              &lt;li&gt;Como controlar o seu dinheiro&lt;/li&gt;
              &lt;li&gt;Como gastar com inteligência&lt;/li&gt;
              &lt;li&gt;Como criar novas fontes de renda&lt;/li&gt;
              &lt;li&gt;Como construir riqueza no longo prazo&lt;/li&gt;
            &lt;/ul&gt;
          &lt;/InfoCard&gt;
        &lt;/section&gt;

        {/* ===== CAPÍTULO 1 ===== */}
        &lt;section id=&quot;chapter-1&quot; className=&quot;mb-16&quot;&gt;
          &lt;ChapterHeader number={1} title=&quot;A Mentalidade do Dinheiro&quot; /&gt;
          &lt;p className=&quot;text-lg leading-relaxed text-foreground mb-4&quot;&gt;
            A primeira regra da riqueza é simples:
          &lt;/p&gt;

          &lt;InfoCard variant=&quot;dark&quot;&gt;
            &lt;p className=&quot;text-2xl font-bold text-center gold-text py-2&quot;&gt;
              🧠 Ser rico começa na mente.
            &lt;/p&gt;
          &lt;/InfoCard&gt;

          &lt;p className=&quot;text-lg leading-relaxed text-foreground mb-6 mt-6&quot;&gt;
            Pessoas que vivem sempre com dificuldades financeiras normalmente:
          &lt;/p&gt;

          &lt;div className=&quot;grid sm:grid-cols-2 gap-4 my-6&quot;&gt;
            &lt;div className=&quot;rounded-xl bg-destructive/5 border border-destructive/20 p-5&quot;&gt;
              &lt;h4 className=&quot;font-semibold text-destructive mb-3 text-lg&quot;&gt;❌ Mentalidade Pobre&lt;/h4&gt;
              &lt;ul className=&quot;space-y-2 text-sm text-foreground&quot;&gt;
                &lt;li&gt;• Gastam tudo que ganham&lt;/li&gt;
                &lt;li&gt;• Compram para impressionar os outros&lt;/li&gt;
                &lt;li&gt;• Buscam prazer imediato&lt;/li&gt;
                &lt;li&gt;• Não planejam o futuro&lt;/li&gt;
              &lt;/ul&gt;
            &lt;/div&gt;
            &lt;div className=&quot;rounded-xl bg-primary/5 border border-primary/20 p-5&quot;&gt;
              &lt;h4 className=&quot;font-semibold text-primary mb-3 text-lg&quot;&gt;✅ Mentalidade Rica&lt;/h4&gt;
              &lt;ul className=&quot;space-y-2 text-sm text-foreground&quot;&gt;
                &lt;li&gt;• Disciplina financeira&lt;/li&gt;
                &lt;li&gt;• Paciência&lt;/li&gt;
                &lt;li&gt;• Foco no longo prazo&lt;/li&gt;
                &lt;li&gt;• Controle emocional&lt;/li&gt;
              &lt;/ul&gt;
            &lt;/div&gt;
          &lt;/div&gt;

          &lt;InfoCard variant=&quot;highlight&quot;&gt;
            &lt;p className=&quot;text-center font-semibold text-lg&quot;&gt;
              💡 A riqueza é resultado de boas decisões repetidas durante muitos anos.
            &lt;/p&gt;
          &lt;/InfoCard&gt;
        &lt;/section&gt;

        {/* ===== CAPÍTULO 2 ===== */}
        &lt;section id=&quot;chapter-2&quot; className=&quot;mb-16&quot;&gt;
          &lt;ChapterHeader number={2} title=&quot;Os 3 Pilares da Riqueza&quot; /&gt;

          {/* Pilar 1 */}
          &lt;div className=&quot;mb-10&quot;&gt;
            &lt;div className=&quot;flex items-center gap-3 mb-4&quot;&gt;
              &lt;span className=&quot;flex h-10 w-10 shrink-0 items-center justify-center rounded-full ebook-gradient-gold text-sm font-bold text-secondary-foreground&quot;&gt;1&lt;/span&gt;
              &lt;h3 className=&quot;text-2xl font-bold text-foreground&quot;&gt;Controle dos gastos&lt;/h3&gt;
            &lt;/div&gt;
            &lt;p className=&quot;text-lg leading-relaxed text-foreground mb-4&quot;&gt;
              Gaste sempre menos do que você ganha. Divida seu dinheiro em:
            &lt;/p&gt;
            &lt;div className=&quot;grid grid-cols-3 gap-3 my-6&quot;&gt;
              {[
                { pct: &quot;50%&quot;, label: &quot;Necessidades&quot;, color: &quot;bg-secondary text-secondary-foreground&quot; },
                { pct: &quot;30%&quot;, label: &quot;Investimentos&quot;, color: &quot;ebook-gradient-gold text-secondary-foreground&quot; },
                { pct: &quot;20%&quot;, label: &quot;Lazer&quot;, color: &quot;bg-muted text-foreground&quot; },
              ].map((item) =&gt; (
                &lt;div key={item.label} className={`rounded-xl p-5 text-center ${item.color}`}&gt;
                  &lt;div className=&quot;text-3xl font-extrabold mb-1&quot;&gt;{item.pct}&lt;/div&gt;
                  &lt;div className=&quot;text-sm font-medium&quot;&gt;{item.label}&lt;/div&gt;
                &lt;/div&gt;
              ))}
            &lt;/div&gt;
          &lt;/div&gt;

          {/* Pilar 2 */}
          &lt;div className=&quot;mb-10&quot;&gt;
            &lt;div className=&quot;flex items-center gap-3 mb-4&quot;&gt;
              &lt;span className=&quot;flex h-10 w-10 shrink-0 items-center justify-center rounded-full ebook-gradient-gold text-sm font-bold text-secondary-foreground&quot;&gt;2&lt;/span&gt;
              &lt;h3 className=&quot;text-2xl font-bold text-foreground&quot;&gt;Reinvestir sempre&lt;/h3&gt;
            &lt;/div&gt;
            &lt;p className=&quot;text-lg leading-relaxed text-foreground mb-4&quot;&gt;
              Dinheiro parado perde valor. Dinheiro investido pode gerar mais dinheiro.
            &lt;/p&gt;
            &lt;InfoCard title=&quot;📈 Exemplos de reinvestimento&quot;&gt;
              &lt;div className=&quot;grid grid-cols-2 sm:grid-cols-3 gap-3&quot;&gt;
                {[&quot;Negócios digitais&quot;, &quot;Vendas online&quot;, &quot;Marketing de afiliados&quot;, &quot;Investimentos financeiros&quot;, &quot;Educação&quot;, &quot;Imóveis&quot;].map((item) =&gt; (
                  &lt;div key={item} className=&quot;rounded-lg bg-primary/10 px-3 py-2 text-center text-sm font-medium text-foreground&quot;&gt;
                    {item}
                  &lt;/div&gt;
                ))}
              &lt;/div&gt;
            &lt;/InfoCard&gt;
          &lt;/div&gt;

          {/* Pilar 3 */}
          &lt;div className=&quot;mb-6&quot;&gt;
            &lt;div className=&quot;flex items-center gap-3 mb-4&quot;&gt;
              &lt;span className=&quot;flex h-10 w-10 shrink-0 items-center justify-center rounded-full ebook-gradient-gold text-sm font-bold text-secondary-foreground&quot;&gt;3&lt;/span&gt;
              &lt;h3 className=&quot;text-2xl font-bold text-foreground&quot;&gt;Pensar em longo prazo&lt;/h3&gt;
            &lt;/div&gt;

            &lt;div className=&quot;grid sm:grid-cols-2 gap-4 my-6&quot;&gt;
              &lt;div className=&quot;rounded-xl bg-destructive/5 border border-destructive/20 p-5&quot;&gt;
                &lt;h4 className=&quot;font-semibold text-destructive mb-3&quot;&gt;⏱️ A maioria pensa em:&lt;/h4&gt;
                &lt;ul className=&quot;space-y-1 text-sm text-foreground&quot;&gt;
                  &lt;li&gt;• Hoje&lt;/li&gt;
                  &lt;li&gt;• Esta semana&lt;/li&gt;
                  &lt;li&gt;• Este mês&lt;/li&gt;
                &lt;/ul&gt;
              &lt;/div&gt;
              &lt;div className=&quot;rounded-xl bg-primary/5 border border-primary/20 p-5&quot;&gt;
                &lt;h4 className=&quot;font-semibold text-primary mb-3&quot;&gt;🏆 Pessoas ricas pensam em:&lt;/h4&gt;
                &lt;ul className=&quot;space-y-1 text-sm text-foreground&quot;&gt;
                  &lt;li&gt;• 5 anos&lt;/li&gt;
                  &lt;li&gt;• 10 anos&lt;/li&gt;
                  &lt;li&gt;• 20 anos&lt;/li&gt;
                &lt;/ul&gt;
              &lt;/div&gt;
            &lt;/div&gt;

            &lt;InfoCard variant=&quot;dark&quot;&gt;
              &lt;p className=&quot;text-center font-semibold text-lg&quot;&gt;
                ⏳ Riqueza leva tempo para ser construída.
              &lt;/p&gt;
            &lt;/InfoCard&gt;
          &lt;/div&gt;
        &lt;/section&gt;

        {/* ===== CAPÍTULO 3 ===== */}
        &lt;section id=&quot;chapter-3&quot; className=&quot;mb-16&quot;&gt;
          &lt;ChapterHeader number={3} title=&quot;Os Maiores Erros Financeiros&quot; /&gt;

          &lt;div className=&quot;space-y-8&quot;&gt;
            {[
              {
                icon: &quot;👔&quot;,
                title: &quot;Querer parecer rico&quot;,
                desc: &quot;Muitas pessoas compram roupas caras, carros caros, celulares novos… Mas não possuem investimentos.&quot;,
              },
              {
                icon: &quot;🪞&quot;,
                title: &quot;Gastar para impressionar&quot;,
                desc: &quot;Se você precisa mostrar riqueza para os outros, provavelmente ainda não a construiu.&quot;,
              },
              {
                icon: &quot;⚡&quot;,
                title: &quot;Impaciência financeira&quot;,
                desc: &quot;Quem busca resultados rápidos geralmente perde dinheiro. Riqueza exige paciência.&quot;,
              },
            ].map((item) =&gt; (
              &lt;div key={item.title} className=&quot;flex gap-5 items-start rounded-xl bg-card border border-border p-6&quot;&gt;
                &lt;span className=&quot;text-3xl shrink-0&quot;&gt;{item.icon}&lt;/span&gt;
                &lt;div&gt;
                  &lt;h4 className=&quot;text-xl font-bold text-foreground mb-2&quot;&gt;{item.title}&lt;/h4&gt;
                  &lt;p className=&quot;text-muted-foreground leading-relaxed&quot;&gt;{item.desc}&lt;/p&gt;
                &lt;/div&gt;
              &lt;/div&gt;
            ))}
          &lt;/div&gt;

          &lt;InfoCard variant=&quot;highlight&quot; title=&quot;💡 Lembre-se&quot;&gt;
            &lt;p className=&quot;font-semibold text-center&quot;&gt;
              Riqueza real é silenciosa. Quem precisa mostrar, normalmente não tem.
            &lt;/p&gt;
          &lt;/InfoCard&gt;
        &lt;/section&gt;

        {/* ===== CAPÍTULO 4 ===== */}
        &lt;section id=&quot;chapter-4&quot; className=&quot;mb-16&quot;&gt;
          &lt;ChapterHeader number={4} title=&quot;Como Gerar Dinheiro Hoje&quot; /&gt;
          &lt;p className=&quot;text-lg leading-relaxed text-foreground mb-6&quot;&gt;
            Algumas formas de criar renda:
          &lt;/p&gt;

          &lt;div className=&quot;grid sm:grid-cols-2 gap-4 my-6&quot;&gt;
            {[
              { icon: &quot;💻&quot;, title: &quot;Marketing digital&quot;, desc: &quot;Promova produtos e serviços pela internet e ganhe comissões ou venda seus próprios produtos.&quot; },
              { icon: &quot;🎬&quot;, title: &quot;Criação de conteúdo&quot;, desc: &quot;Crie vídeos, textos ou podcasts e monetize com anúncios, parcerias e vendas.&quot; },
              { icon: &quot;🛒&quot;, title: &quot;Venda de produtos online&quot;, desc: &quot;Venda produtos físicos ou digitais em marketplaces ou na sua própria loja.&quot; },
              { icon: &quot;🛠️&quot;, title: &quot;Serviços digitais&quot;, desc: &quot;Ofereça habilidades como design, programação, tradução ou consultoria.&quot; },
            ].map((item) =&gt; (
              &lt;div key={item.title} className=&quot;rounded-xl bg-card border border-border p-5&quot;&gt;
                &lt;div className=&quot;text-3xl mb-3&quot;&gt;{item.icon}&lt;/div&gt;
                &lt;h4 className=&quot;font-semibold text-foreground mb-2 text-lg&quot;&gt;{item.title}&lt;/h4&gt;
                &lt;p className=&quot;text-sm text-muted-foreground&quot;&gt;{item.desc}&lt;/p&gt;
              &lt;/div&gt;
            ))}
          &lt;/div&gt;

          &lt;InfoCard variant=&quot;dark&quot;&gt;
            &lt;p className=&quot;text-center font-semibold text-lg&quot;&gt;
              🚀 O segredo é começar pequeno e crescer com consistência.
            &lt;/p&gt;
          &lt;/InfoCard&gt;
        &lt;/section&gt;

        {/* ===== CAPÍTULO 5 ===== */}
        &lt;section id=&quot;chapter-5&quot; className=&quot;mb-16&quot;&gt;
          &lt;ChapterHeader number={5} title=&quot;A Fórmula da Liberdade Financeira&quot; /&gt;
          &lt;p className=&quot;text-lg leading-relaxed text-foreground mb-6&quot;&gt;
            A verdadeira riqueza não está no luxo. Ela está no &lt;strong&gt;controle da própria vida&lt;/strong&gt;:
          &lt;/p&gt;

          &lt;div className=&quot;grid grid-cols-2 sm:grid-cols-4 gap-4 my-8&quot;&gt;
            {[
              { icon: &quot;⏰&quot;, label: &quot;Tempo&quot; },
              { icon: &quot;🧭&quot;, label: &quot;Decisões&quot; },
              { icon: &quot;💼&quot;, label: &quot;Trabalho&quot; },
              { icon: &quot;🌅&quot;, label: &quot;Futuro&quot; },
            ].map((item) =&gt; (
              &lt;div key={item.label} className=&quot;rounded-xl ebook-gradient-navy text-white p-6 text-center&quot;&gt;
                &lt;div className=&quot;text-3xl mb-2&quot;&gt;{item.icon}&lt;/div&gt;
                &lt;div className=&quot;text-sm font-semibold&quot;&gt;{item.label}&lt;/div&gt;
              &lt;/div&gt;
            ))}
          &lt;/div&gt;

          &lt;InfoCard variant=&quot;highlight&quot;&gt;
            &lt;p className=&quot;text-center font-semibold text-lg&quot;&gt;
              🔑 Liberdade financeira = ter suas necessidades cobertas sem depender de um emprego.
            &lt;/p&gt;
          &lt;/InfoCard&gt;
        &lt;/section&gt;

        {/* ===== CONCLUSÃO ===== */}
        &lt;section id=&quot;chapter-6&quot; className=&quot;mb-16&quot;&gt;
          &lt;ChapterHeader number={6} title=&quot;Conclusão&quot; /&gt;
          &lt;p className=&quot;text-lg leading-relaxed text-foreground mb-4&quot;&gt;
            Riqueza não vem de parecer bem-sucedido.
          &lt;/p&gt;
          &lt;p className=&quot;text-lg leading-relaxed text-foreground mb-4&quot;&gt;
            Ela vem de construir algo sólido ao longo do tempo.
          &lt;/p&gt;
          &lt;p className=&quot;text-lg leading-relaxed text-foreground mb-6&quot;&gt;
            &lt;strong&gt;Disciplina, paciência e visão de longo prazo&lt;/strong&gt; são fundamentais.
          &lt;/p&gt;

          {/* Prompt diário */}
          &lt;div className=&quot;rounded-2xl ebook-gradient-hero p-8 sm:p-12 text-center relative overflow-hidden&quot;&gt;
            &lt;div className=&quot;absolute inset-0 opacity-10&quot; style={{
              backgroundImage: 'radial-gradient(circle at 50% 50%, hsl(43, 90%, 50%) 0%, transparent 60%)'
            }} /&gt;
            &lt;div className=&quot;relative&quot;&gt;
              &lt;p className=&quot;text-primary uppercase tracking-[0.3em] text-xs font-semibold mb-6&quot;&gt;
                Repita diariamente
              &lt;/p&gt;
              &lt;div className=&quot;space-y-3 text-white text-lg sm:text-xl leading-relaxed italic font-light&quot;&gt;
                &lt;p&gt;&quot;Eu controlo meu dinheiro.&lt;/p&gt;
                &lt;p&gt;Gasto com inteligência e invisto com paciência.&lt;/p&gt;
                &lt;p&gt;Todos os dias construo um futuro financeiro mais forte.&lt;/p&gt;
                &lt;p&gt;Meu objetivo não é parecer rico.&lt;/p&gt;
                &lt;p&gt;Meu objetivo é conquistar &lt;span className=&quot;gold-text font-semibold not-italic&quot;&gt;liberdade financeira&lt;/span&gt;.&quot;&lt;/p&gt;
              &lt;/div&gt;
              &lt;div className=&quot;w-20 h-px bg-gradient-to-r from-transparent via-primary to-transparent mx-auto mt-8&quot; /&gt;
            &lt;/div&gt;
          &lt;/div&gt;
        &lt;/section&gt;

        {/* Footer */}
        &lt;footer className=&quot;text-center py-8 border-t border-border&quot;&gt;
          &lt;p className=&quot;text-muted-foreground text-sm&quot;&gt;
            © 2026 — &lt;span className=&quot;font-semibold&quot;&gt;MENTE RICA&lt;/span&gt; — Todos os direitos reservados.
          &lt;/p&gt;
        &lt;/footer&gt;
      &lt;/div&gt;
    &lt;/EbookLayout&gt;
  );
};

export default Index;
</code></pre>

Q: Testing if a dialog is pop-up with Playwright for Java A: <p>To test whether a <strong>dialog pop-up appears</strong> in <strong>Playwright using Java</strong>, you usually listen for the dialog event . This works for browser dialogs like <strong>alert, confirm, and prompt</strong>.</p>
<pre><code>

import com.microsoft.playwright.*;

public class DialogTest {
    public static void main(String[] args) {
        try (Playwright playwright = Playwright.create()) {
            Browser browser = playwright.chromium().launch(
                    new BrowserType.LaunchOptions().setHeadless(false)
            );

            Page page = browser.newPage();

            page.onDialog(dialog -&gt; {
                System.out.println(&quot;Dialog message: &quot; + dialog.message());
                dialog.accept(); // or dialog.dismiss();
            });

            page.navigate(&quot;https://example.com&quot;);

            page.click(&quot;#open-dialog&quot;);
        }
    }
}
</code></pre>
